```java
// ArchUnit test, runs as a normal JUnit test in CI
import com.tngtech.archunit.lang.ArchRule;
import static com.tngtech.archunit.library.dependencies.SlicesRuleDefinition.slices;
import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;

class ArchitectureTest {

    @ArchTest
    static final ArchRule data_layer_must_not_depend_on_presentation =
        noClasses().that().resideInAPackage("..data..")
            .should().dependOnClassesThat().resideInAPackage("..presentation..");

    @ArchTest
    static final ArchRule domain_must_not_depend_on_any_infrastructure =
        noClasses().that().resideInAPackage("..domain..")
            .should().dependOnClassesThat().resideInAnyPackage("..infrastructure..", "..web..");
}
```

Either rule failing means CI turns red on the exact commit that introduced the violation — the same feedback loop a broken business-logic test gives you, now covering the shape of the codebase itself.
